mapper.sql:
inner join (
    select distinct sr.event_team_id, sr.season_id
    from basket_tournament_season_roster sr
    where sr.is_delete = 0
      and sr.event_team_id is not null
      and (
          sr.member_id = #{memberId}

              or sr.player_id = #{playerId}

      )
) my_et on (m.home_event_team_id = my_et.event_team_id or m.away_event_team_id = my_et.event_team_id)

m.is_delete = 0 and m.publish_status = 1 and m.match_status != 0 and m.schedule_batch_id is not null and m.home_event_team_id is not null and m.away_event_team_id is not null
and m.season_id = #{query.seasonId}
and m.platform_code = #{query.platformCode}
and m.scheduled_start_time >= #{startTime}
and m.scheduled_start_time < #{endTimeExclusive}
and m.match_status in (1, 2, 4)
and m.match_status = 2
and m.match_status = 3
and m.match_status = 5

mapper.select:
select s.matchId, s.myEventTeamId from (
) s inner join basket_match m on m.id = s.matchId order by (m.scheduled_start_time is null) asc,
m.scheduled_start_time desc
m.scheduled_start_time asc
, m.sort_no asc, m.id asc limit #{offset}, #{limit}

select distinct s.id as seasonId, s.season_name as seasonName, s.season_no as seasonCode, t.tournament_name as tournamentName from basket_tournament_season_roster sr inner join basket_tournament_season s on s.id = sr.season_id and s.is_delete = 0 left join basket_tournament t on t.id = s.tournament_id and t.is_delete = 0 where sr.is_delete = 0 and sr.event_team_id is not null and ( sr.member_id = #{memberId}
or sr.player_id = #{playerId}
) and exists ( select 1 from basket_match m where m.is_delete = 0 and m.publish_status = 1 and m.match_status != 0 and m.schedule_batch_id is not null and (m.home_event_team_id = sr.event_team_id or m.away_event_team_id = sr.event_team_id) ) order by s.id desc
